//! An explicit author change and its authored dependencies. No inferred canon,
//! automatic chronology scheduling, manuscript reads, or silent cascades.
use super::*;
use std::collections::{HashSet, BTreeMap};

const WORK_LIMIT: usize = 20_000;
const DEPENDENCY_LIMIT: usize = 200;
fn rows<'a>(value:&'a Value,key:&str)->&'a [Value]{value[key].as_array().map(Vec::as_slice).unwrap_or(&[])}
fn string(value:&Value,key:&str)->String{value[key].as_str().unwrap_or("").into()}
fn excerpt(value:&str)->String{let mut chars=value.chars();let mut result:String=chars.by_ref().take(2_000).collect();if chars.next().is_some(){result.push('…');}result}
#[derive(Clone,Debug,PartialEq)]struct Dependency{kind:String,id:String,label:String,reason:String}
#[derive(Default,Debug)]struct RipplePreview{dependencies:Vec<Dependency>,limited:bool,errors:Vec<String>,changes:Vec<(String,Value,Value)>}
struct Traversal{work:usize,seen:HashSet<String>,view:RipplePreview}
impl Traversal{
    fn visit(&mut self)->bool{self.work+=1;if self.work>WORK_LIMIT{self.view.limited=true;false}else{true}}
    fn add(&mut self,kind:&str,id:&str,label:&str,reason:&str){if self.seen.insert(format!("{kind}:{id}")){if self.view.dependencies.len()<DEPENDENCY_LIMIT{self.view.dependencies.push(Dependency{kind:kind.into(),id:id.into(),label:excerpt(label),reason:reason.into()});}else{self.view.limited=true;}}}
    fn scene(&mut self,id:&str,scenes:&[(String,String)],reason:&str){self.add("Scene",id,scenes.iter().find(|(s,_)|s==id).map(|(_,name)|name.as_str()).unwrap_or("Missing scene"),reason);}
}
fn meaning(fact:&Value)->Value{json!([fact["subjectId"],fact["property"],fact["value"],fact["status"],fact["confirmed"],fact["observerId"],fact["eventId"],fact["untilEventId"]])}
fn preview(before:&Value,after:&Value,scenes:&[(String,String)])->RipplePreview{
    let mut traversal=Traversal{work:0,seen:HashSet::new(),view:RipplePreview::default()};let mut facts=HashSet::<String>::new();let mut events=HashSet::<String>::new();let mut subjects=HashSet::<String>::new();
    let next_facts=rows(after,"facts").iter().filter_map(|f|Some((f["id"].as_str()?,f))).collect::<HashMap<_,_>>();let next_events=rows(after,"events").iter().filter_map(|e|Some((e["id"].as_str()?,e))).collect::<HashMap<_,_>>();
    for fact in rows(before,"facts"){
        if !traversal.visit(){break;}let Some(id)=fact["id"].as_str()else{continue;};let next=next_facts.get(id).copied().cloned().unwrap_or(Value::Null);
        if next.is_null()||meaning(fact)!=meaning(&next){facts.insert(id.into());if let Some(id)=fact["subjectId"].as_str(){subjects.insert(id.into());}if let Some(id)=next["subjectId"].as_str(){subjects.insert(id.into());}traversal.view.changes.push(("Fact".into(),fact.clone(),next));}
    }
    for event in rows(before,"events"){
        if !traversal.visit(){break;}let Some(id)=event["id"].as_str()else{continue;};let next=next_events.get(id).copied().cloned().unwrap_or(Value::Null);
        if next.is_null()||event["time"]!=next["time"]{events.insert(id.into());traversal.view.changes.push(("Event time".into(),event.clone(),next));}
    }
    for doc in [before,after]{
        let mut relative=BTreeMap::<String,Vec<&Value>>::new();for event in rows(doc,"events"){if !traversal.visit(){break;}if event["time"]["kind"]=="relative"{if let Some(id)=event["time"]["eventId"].as_str(){relative.entry(id.into()).or_default().push(event);}}}
        let mut queue=events.iter().cloned().collect::<Vec<_>>();let mut visited=events.clone();let mut cursor=0;
        while cursor<queue.len(){if !traversal.visit(){break;}let current=queue[cursor].clone();cursor+=1;for event in relative.get(&current).into_iter().flatten(){if !traversal.visit(){break;}if let Some(id)=event["id"].as_str(){if visited.insert(id.into()){events.insert(id.into());queue.push(id.into());traversal.add("Relative event",id,&string(event,"title"),"Authored relative date depends on changed time");}}}}
        for event in rows(doc,"events"){if !traversal.visit(){break;}if event["id"].as_str().is_some_and(|id|events.contains(id)){for id in rows(event,"sceneIds").iter().filter_map(Value::as_str){if !traversal.visit(){break;}traversal.scene(id,scenes,"Explicit occurrence-event link");}}}
        for fact in rows(doc,"facts"){if !traversal.visit(){break;}if ["eventId","untilEventId"].iter().any(|key|fact[*key].as_str().is_some_and(|id|events.contains(id))){if let Some(id)=fact["id"].as_str(){facts.insert(id.into());traversal.add("Fact",id,&format!("{}: {}",string(fact,"property"),string(fact,"value")),"Authored fact applicability references affected event time");}}}
        for entry in rows(doc,"knowledge"){if !traversal.visit(){break;}if entry["factId"].as_str().is_some_and(|id|facts.contains(id))||entry["scope"]["kind"]=="events"&&["fromEventId","untilEventId"].iter().any(|key|entry["scope"][*key].as_str().is_some_and(|id|events.contains(id))){traversal.add("Knowledge",entry["id"].as_str().unwrap_or(""),&format!("{}: {}",string(entry,"stance"),string(&entry["factSnapshot"],"property")),"Recorded fact snapshot stays unchanged; its applicability may need author review");if entry["scope"]["kind"]=="scenes"{for id in rows(&entry["scope"],"sceneIds").iter().filter_map(Value::as_str){if !traversal.visit(){break;}traversal.scene(id,scenes,"Explicit knowledge scope");}}}}
        for reveal in rows(doc,"readerReveals"){if !traversal.visit(){break;}if reveal["factId"].as_str().is_some_and(|id|facts.contains(id))||reveal["eventId"].as_str().is_some_and(|id|events.contains(id)){traversal.add("Reader reveal",reveal["id"].as_str().unwrap_or(""),"Authored reveal","Explicit reveal references affected fact or event");if let Some(id)=reveal["scene"]["id"].as_str(){traversal.scene(id,scenes,"Authored reveal scene");}}}
        for constraint in rows(doc,"constraints"){if !traversal.visit(){break;}if ["beforeId","afterId"].iter().any(|key|constraint[*key].as_str().is_some_and(|id|events.contains(id))){traversal.add("Constraint",constraint["id"].as_str().unwrap_or(""),&string(constraint,"notes"),if constraint["confirmed"]==true{"Confirmed authored time constraint; not automatically rescheduled"}else{"Unconfirmed authored time constraint"});}}
        let relevant=|link:&Value|link["id"].as_str().is_some_and(|id|link["kind"]=="event"&&events.contains(id)||link["kind"]=="record"&&subjects.contains(id));
        for record in rows(doc,"records"){
            if !traversal.visit(){break;}let mut linked=record["id"].as_str().is_some_and(|id|subjects.contains(id));
            for link in rows(record,"links"){if !traversal.visit(){break;}linked|=relevant(link);}
            for value in record["values"].as_object().into_iter().flat_map(|v|v.values()){for link in value.as_array().into_iter().flatten(){if !traversal.visit(){break;}linked|=relevant(link);}}
            if linked{traversal.add("Record",record["id"].as_str().unwrap_or(""),&string(record,"name"),"Canonical subject or explicitly linked event");for link in rows(record,"links"){if !traversal.visit(){break;}if link["kind"]=="scene"{if let Some(id)=link["id"].as_str(){traversal.scene(id,scenes,"Explicit record scene link");}}}}
        }
        for point in rows(doc,"plotPoints"){if !traversal.visit(){break;}let mut linked=false;for link in rows(point,"links"){if !traversal.visit(){break;}linked|=relevant(link);}if linked{traversal.add("Plot point",point["id"].as_str().unwrap_or(""),&string(point,"title"),"Explicit affected record/event link");}}
        for board in rows(doc,"boards"){if !traversal.visit(){break;}let mut cards=HashSet::new();for card in rows(board,"cards"){if !traversal.visit(){break;}if relevant(&card["reference"]){if let Some(id)=card["id"].as_str(){cards.insert(id);traversal.add("Board card",id,&string(card,"title"),"Representation of an explicitly affected record or event");}}}for edge in rows(board,"edges"){if !traversal.visit(){break;}if ["fromId","toId"].iter().any(|key|edge[*key].as_str().is_some_and(|id|cards.contains(id))){traversal.add("Board edge",edge["id"].as_str().unwrap_or(""),&string(edge,"label"),"Touches an affected authored representation");}}}
        for issue in rows(doc,"issues"){if !traversal.visit(){break;}let mut linked=false;for link in rows(issue,"links"){if !traversal.visit(){break;}linked|=relevant(link);}for evidence in rows(issue,"evidence"){if !traversal.visit(){break;}linked|=relevant(&evidence["link"]);}if linked{traversal.add("Issue",issue["id"].as_str().unwrap_or(""),&string(issue,"description"),"Manual issue/evidence references an affected record or event");}}
    }
    if let Err(error)=novel_storage::planning_validation::validate_transition(Some(before),after){traversal.view.errors.push(error);}
    traversal.view
}
/// An authored variant change replaces its recognized fields only. Unknown
/// retained fields are preserved rather than silently erased by this editor.
fn merge_time(original:&Value,authored:&Value)->Value{let mut result=original.clone();if !result.is_object(){result=json!({});}let object=result.as_object_mut().unwrap();for key in ["kind","day","start","end","eventId","offsetDays","label"]{object.remove(key);}if let Some(fields)=authored.as_object(){for (key,value) in fields{object.insert(key.clone(),value.clone());}}result}
fn describe_change(kind:&str,row:&Value,doc:&Value)->String{
    if row.is_null(){return "Removed by your explicit proposal".into();}
    if kind=="Fact"{format!("{}: {}\n{} · {}",excerpt(&string(row,"property")),excerpt(&string(row,"value")),string(row,"status"),if row["confirmed"]==true{"Author-approved canon"}else{"Unapproved"})}
    else{let time=&row["time"];let description=match time["kind"].as_str(){Some("unknown")=>"Unknown story time".into(),Some("fixed")=>format!("Day {} · {}",time["day"],string(time,"label")),Some("bounds"|"interval")=>format!("{} to {} · {}",time["start"],time["end"],string(time,"label")),Some("relative")=>format!("Relative to {} · {} days",rows(doc,"events").iter().find(|e|e["id"]==time["eventId"]).map(|e|string(e,"title")).unwrap_or_else(||"Missing event".into()),time["offsetDays"]),_=>"Unsupported authored time".into()};format!("{}\n{description}",excerpt(&string(row,"title")))}
}
fn report(view:&RipplePreview,before:&Value,after:&Value)->String{
    let mut out=String::from("Your proposed authored change\n\n");for (kind,old,next) in &view.changes{out.push_str(&format!("{kind}\nBefore\n{}\n\nAfter\n{}\n\n",describe_change(kind,old,before),describe_change(kind,next,after)));}
    out.push_str("Authored dependencies to review\n\n");if view.dependencies.is_empty(){out.push_str("No explicit dependencies were found in the examined scope. This is not a prose or continuity verdict.\n\n");}
    for dependency in &view.dependencies{out.push_str(&format!("{} · {}\n{}\n\n",dependency.kind,dependency.label,dependency.reason));}
    if view.limited{out.push_str("Preview limit reached. Some authored dependencies are omitted; no complete chronology validation is claimed.\n\n");}
    for error in &view.errors{out.push_str(&format!("Cannot apply: {error}\nResolve retained links in Story notes, then refresh this page.\n\n"));}
    out.push_str("Applying saves exactly this proposed planning payload. Other facts, dates, knowledge snapshots, reveals and manuscript text are not rewritten.");out
}

